preset.warp:
uniform sampler2D sampler_cover;
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The cover's average colour at full brightness; a grey cover gives way
// to the accent, or the bands would be grey on grey.
vec3 coverTone() {
  vec3 c = textureLod(sampler_cover, vec2(0.5), 10.0).rgb;
  float top = max(max(c.r, c.g), c.b);
  float saturation = top - min(min(c.r, c.g), c.b);
  vec3 tone = top > 0.01 ? c / top * 0.85 : vec3(0.0);
  return mix(accent() * 0.7, tone, smoothstep(0.05, 0.25, saturation));
}
// The Mandelbrot set's main cardioid and big bulb are inside for certain:
// skipping their iterations is most of the cost at its overview.
bool surelyInside(vec2 c) {
  float x = c.x - 0.25;
  float q = x * x + c.y * c.y;
  if (q * (q + x) < 0.25 * c.y * c.y) return true;
  return (c.x + 1.0) * (c.x + 1.0) + c.y * c.y < 0.0625;
}
vec2 turn2(vec2 v, float a) {
  return vec2(cos(a) * v.x - sin(a) * v.y, sin(a) * v.x + cos(a) * v.y);
}
// The colour at one point on screen: q1/q2 the centre, q3 the height of
// the screen in the fractal's plane, q4 its turn, q5 the kind (0 the
// Mandelbrot set, 1 a Julia set of c = q6/q7).
vec3 fractalAt(vec2 s) {
  vec2 p = vec2(q1, q2) + turn2(s, q4) * q3;
  float pixel = q3 / texsize.y;
  vec3 col = vec3(0.004) + accent() * 0.02;
  bool julia = q5 > 0.5;
  if (!julia && surelyInside(p)) return col;
  vec2 z = julia ? p : vec2(0.0);
  vec2 c = julia ? vec2(q6, q7) : p;
  vec2 dz = julia ? vec2(1.0, 0.0) : vec2(0.0);
  int limit = int(q9);
  float escaped = -1.0;
  float r2 = 0.0;
  for (int i = 0; i < 420; i++) {
    if (i >= limit) break;
    dz = 2.0 * vec2(z.x * dz.x - z.y * dz.y, z.x * dz.y + z.y * dz.x);
    if (!julia) dz += vec2(1.0, 0.0);
    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
    r2 = dot(z, z);
    if (r2 > 65536.0) {
      escaped = float(i);
      break;
    }
  }
  if (escaped < 0.0) return col;
  // Smooth iteration count, so the bands have no steps - counting the
  // iterations a Julia scene skipped by being redrawn further out (q20),
  // or each of those jumps would show.
  float mu = escaped + 1.0 - log2(0.5 * log2(r2)) + q20;
  // Distance to the set, in pixels: its edge lights up.
  float dist = 0.5 * sqrt(r2) * log(r2) / max(length(dz), 1e-30) / pixel;
  float t = mu * 0.025 + q8;
  vec3 a = accent();
  vec3 band = mix(a, coverTone(), 0.5 + 0.5 * cos(6.2832 * t));
  float ridge = 0.5 + 0.5 * cos(6.2832 * t * 3.0);
  col = band * (0.12 + 0.6 * ridge * ridge);
  // Far from the set, few iterations: kept dark, so the set stands out.
  col *= smoothstep(0.0, 10.0, mu);
  // Thin, and fainter where the filaments crowd together.
  float edge = exp(-dist * 2.0) * mix(1.0, 0.35, smoothstep(150.0, 350.0, mu));
  col += mix(a, vec3(1.0), 0.5) * edge * (0.3 + 0.3 * min(q11, 1.5));
  return col;
}
 shader_body {
  vec2 s = (uv_orig - 0.5) / aspect.yx;
  s.y = -s.y;
  // This frame's sample sits somewhere else inside the pixel each time,
  // and last frame's picture at the same spot of the fractal is blended
  // in: an average over many frames, which keeps the filaments from
  // flickering.
  vec3 now = fractalAt(s + vec2(q18, q19) / texsize.y);
  vec2 before = turn2(s, q14) * q13 + vec2(q15, q16);
  vec2 beforeUv = vec2(before.x, -before.y) * aspect.yx + 0.5;
  float known = step(0.0, beforeUv.x) * step(beforeUv.x, 1.0) * step(0.0, beforeUv.y) * step(beforeUv.y, 1.0);
  ret = mix(now, texture(sampler_main, beforeUv).rgb, q17 * known);
 }

preset.comp:
shader_body {
 vec3 col = texture(sampler_main, uv).rgb;
 vec3 glow = vec3(0.0);
 float spin = 6.2832 * fract(52.9829 * fract(dot(uv * texsize.xy, vec2(0.06711, 0.00584))));
 for (int i = 0; i < 16; i++) {
   float a = float(i) * 2.39996 + spin;
   float r = 0.012 * sqrt((float(i) + 0.5) / 16.0);
   vec2 o = vec2(cos(a), sin(a)) * r * vec2(aspect.y, 1.0);
   glow += max(texture(sampler_main, uv + o).rgb - 0.45, 0.0);
 }
 col += glow / 16.0 * 1.4;
 // A beat flashes what is bright: the edge of the set.
 col += max(col - 0.35, 0.0) * q10 * 1.6;
 col = 1.0 - exp(-col * 1.5);
 col *= 1.0 - 0.45 * pow(clamp(rad * 1.25, 0.0, 1.0), 2.5);
 // Between two fractals the picture dims and comes back.
 ret = col * q12;
}
